using UnityEngine;

namespace RealisticCarRacing.Vehicles
{
    /// <summary>
    /// Shared detail meshes and materials for a car's look: wheels (tyre, rim, brake disc, caliper), glass, lamps
    /// and cabin trim. Wheel meshes are unit size (radius 1 around the X axle, width 1, outer face towards +X) and are
    /// scaled to the car's wheel radius. Generated by RealisticCarRacing &gt; Create Game Content; an imported car
    /// model can use the materials and keep its own meshes.
    /// </summary>
    [CreateAssetMenu(fileName = "CarVisualKit", menuName = "RealisticCarRacing/Car Visual Kit")]
    public sealed class CarVisualKit : ScriptableObject
    {
        [Header("Wheel meshes (unit size)")]
        public Mesh tyre;
        [Tooltip("Coarse tyre for distant cars (LOD 1).")]
        public Mesh tyreLow;
        public Mesh rim;
        public Mesh brakeDisc;
        [Tooltip("Does not spin: follows the wheel's steering only.")]
        public Mesh caliper;

        [Header("Placeholder body")]
        [Tooltip("Glass of the placeholder cabin (fits the cabin collider).")]
        public Mesh greenhouseGlass;
        [Tooltip("Roof and pillars of the placeholder cabin; drawn with the body paint.")]
        public Mesh greenhouseFrame;

        [Header("Materials")]
        public Material tyreRubber;
        public Material rimMetal;
        public Material brakeDiscMetal;
        public Material caliperPaint;
        public Material glass;
        public Material leather;
        public Material plastic;
        [Tooltip("Roof lining fabric.")]
        public Material headliner;
        public Material gaugeFace;
        public Material gaugeNeedle;
        public Material screen;

        [Header("Wheel designs")]
        [Tooltip("Rim choices offered in the garage; the first is the default. Visual only: every design fits the same tyre.")]
        public WheelDesign[] wheelDesigns = System.Array.Empty<WheelDesign>();

        [Header("Lamps")]
        public Material headlight;
        [Tooltip("Tail lamps with the brake released (position lights).")]
        public Material tailLight;
        public Material brakeLight;
        public Material reverseLightOff;
        public Material reverseLightOn;

        public int WheelDesignCount => Mathf.Max(1, wheelDesigns.Length);

        /// <summary>Rim mesh and finish for a garage wheel choice (falls back to the kit's own rim).</summary>
        public (Mesh mesh, Material material) Rim(int design)
        {
            if (wheelDesigns.Length == 0)
                return (rim, rimMetal);
            var chosen = wheelDesigns[Mathf.Abs(design) % wheelDesigns.Length];
            return (chosen.rim, chosen.finish);
        }
    }

    /// <summary>A rim style: unit-size mesh (same convention as <see cref="CarVisualKit.rim"/>) and its finish.</summary>
    [System.Serializable]
    public sealed class WheelDesign
    {
        public string id;
        public string displayName;
        [Tooltip("Finish shown under the name, e.g. \"Gloss black\".")]
        public string finishName;
        public Mesh rim;
        public Material finish;
    }
}
